  $('#shopDetailMode').value=detailTab;$('#shopPinSelected').setAttribute('aria-pressed',String(compareIds.has(model.selectedId)));$('#shopPinSelected').textContent=compareIds.has(model.selectedId)?'Remove comparison':'Pin to compare';for(const button of $('.armory-detail-tabs').querySelectorAll('button'))button.setAttribute('aria-pressed',String(button.getAttribute('data-detail-tab')===detailTab));
  if(mode==='compare')renderComparison();if(focusId||needsFocus)restoreFocus(activeId);return result;
