  const fields=current.metrics.map(metric=>{const other=next.metrics.find(value=>value.key===metric.key),delta=other?other.value-metric.value:0;return `<tr><th scope="row">${escape(metric.label)}<small>${escape(metric.scope)}</small></th><td>${escape(metricValue(metric))}</td><td>${escape(metricValue(other))}${delta?`<small class="stat-delta">${delta>0?'+':''}${number(delta)}</small>`:''}</td></tr>`;}).join('');
