  if($('#shopCompareRank')){$('#shopCompareRank').value=compareRank;$('#shopCompareRank').onchange=()=>{compareRank=$('#shopCompareRank').value;renderComparison();focus('shopCompareRank');};}$('#shopCompareBack').onclick=closeComparison;
