 function toggleCompare(id,focusId){if(compareIds.has(id))compareIds.delete(id);else if(compareIds.size<2)compareIds.add(id);else{say('Two cards are already pinned. Remove one before adding another.');return;}refresh({focusId});say(`${compareIds.size} of 2 cards pinned for comparison.`);}
